<script setup lang="ts">
import {computed,ref} from 'vue';import {useRouter} from 'vue-router';import {usePhase1} from '@/pinia/phase1';import {dateText,eventNames,phaseSkills} from './catalog';import CorrectionDialog from './CorrectionDialog.vue';
const props=defineProps<{orderId:string}>();const s=usePhase1();const router=useRouter();const correction=ref('');const events=computed(()=>s.events.filter(e=>e.orderId===props.orderId).slice().reverse());const anomalies=computed(()=>s.anomalies.filter(a=>a.orderId===props.orderId));
</script>
<template><h2>基础事件与研判结果 · {{events.length}}条</h2><article v-for="e in events" :key="e.id" class="p1-row"><div class="p1-actions"><strong>{{eventNames[e.type]}} · {{e.phase==='enter'?'进入':e.phase==='exit'?'离开':e.phase==='recovered'?'恢复':'告警'}} · {{e.address}}</strong><button @click="correction=e.id">纠正结果</button></div><small>{{e.id}} · 发生{{dateText(e.occurredAt)}} · 接收{{dateText(e.receivedAt)}} · 配置v{{e.configVersion}}</small><p v-if="e.type==='weather'">{{e.weatherType}} · {{e.message}}</p><p>{{e.result}}</p><small>负责研判：{{e.taskIds.map(id=>phaseSkills.find(t=>t.id===id)?.name).join('、')||'未选择状态任务'}}</small><details v-if="e.corrections?.length"><summary>原始结果与纠正记录</summary><p>原始结果：{{e.originalResult}}</p><p v-for="(c,i) in e.corrections" :key="i">{{dateText(c.at)}} · {{c.operator}}：{{c.before}} → {{c.after}}；{{c.reason}}</p></details><button @click="router.push({path:'/index/daily-tasks',query:{projectId:e.projectId,orderId:e.orderId,taskId:e.taskIds[0]}})">查看任务结果</button></article><p v-if="!events.length" class="p1-empty">暂无基础事件</p><h2>异常与本地计时结果</h2><article v-for="a in anomalies" :key="a.id" class="p1-row"><div class="p1-actions"><strong>{{a.kind}} · {{a.status==='active'?'未恢复':a.status==='corrected'?'已纠正':'已恢复'}}</strong><button @click="correction=a.id">纠正结果</button></div><p>{{a.reason}}</p><small>{{a.id}} · {{dateText(a.firstAt)}} · 配置v{{a.configVersion}} · 重复提醒{{a.repeatCount}}次</small><details v-if="a.corrections?.length"><summary>纠正记录</summary><p v-for="(c,i) in a.corrections" :key="i">{{dateText(c.at)}} · {{c.operator}} · {{c.after}}；{{c.reason}}</p></details></article><CorrectionDialog v-if="correction" :key="correction" :id="correction" @close="correction=''"/></template>
